CREATE TYPE "WorkspaceRole" AS ENUM ('OWNER','ADMIN','MEMBER');
CREATE TYPE "MembershipStatus" AS ENUM ('ACTIVE','BLOCKED');
CREATE TYPE "InvitationStatus" AS ENUM ('PENDING','ACCEPTED','REJECTED','EXPIRED');
CREATE TYPE "TaskStatus" AS ENUM ('PENDING','IN_PROGRESS','COMPLETED');
CREATE TYPE "TaskPriority" AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TABLE "User" ("id" UUID PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Credential" ("userId" UUID PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Profile" ("userId" UUID PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "jobTitle" TEXT, "avatarKey" TEXT, "photoUrl" TEXT);
CREATE TABLE "Workspace" ("id" UUID PRIMARY KEY, "name" TEXT NOT NULL, "ownerId" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Membership" ("workspaceId" UUID NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "role" "WorkspaceRole" NOT NULL DEFAULT 'MEMBER', "status" "MembershipStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("workspaceId","userId"));
CREATE TABLE "Invitation" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE, "email" TEXT NOT NULL, "role" "WorkspaceRole" NOT NULL DEFAULT 'MEMBER', "tokenHash" TEXT NOT NULL UNIQUE, "status" "InvitationStatus" NOT NULL DEFAULT 'PENDING', "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Project" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE, "createdById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "color" TEXT NOT NULL, "startsAt" TIMESTAMP(3), "dueAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Task" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE, "projectId" UUID NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE, "createdById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "status" "TaskStatus" NOT NULL DEFAULT 'PENDING', "priority" "TaskPriority" NOT NULL DEFAULT 'MEDIUM', "dueAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TaskAssignee" ("taskId" UUID NOT NULL REFERENCES "Task"("id") ON DELETE CASCADE, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, PRIMARY KEY ("taskId","userId"));
CREATE TABLE "Comment" ("id" UUID PRIMARY KEY, "taskId" UUID NOT NULL REFERENCES "Task"("id") ON DELETE CASCADE, "authorId" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Activity" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE, "actorId" UUID REFERENCES "User"("id") ON DELETE SET NULL, "type" TEXT NOT NULL, "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Notification" ("id" UUID PRIMARY KEY, "workspaceId" UUID REFERENCES "Workspace"("id") ON DELETE CASCADE, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "type" TEXT NOT NULL, "payload" JSONB NOT NULL, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "UserPreference" ("userId" UUID PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE, "notifications" BOOLEAN NOT NULL DEFAULT true, "compact" BOOLEAN NOT NULL DEFAULT false, "weeklySummary" BOOLEAN NOT NULL DEFAULT true, "theme" TEXT NOT NULL DEFAULT 'Claro');
CREATE TABLE "Session" ("id" UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Membership_userId_status_idx" ON "Membership"("userId","status"); CREATE INDEX "Invitation_workspaceId_email_status_idx" ON "Invitation"("workspaceId","email","status"); CREATE INDEX "Project_workspaceId_idx" ON "Project"("workspaceId"); CREATE INDEX "Task_workspaceId_status_idx" ON "Task"("workspaceId","status"); CREATE INDEX "Task_projectId_idx" ON "Task"("projectId"); CREATE INDEX "Task_dueAt_idx" ON "Task"("dueAt"); CREATE INDEX "TaskAssignee_userId_idx" ON "TaskAssignee"("userId"); CREATE INDEX "Activity_workspaceId_createdAt_idx" ON "Activity"("workspaceId","createdAt"); CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt"); CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId","expiresAt");
